</head><body><h1>Weekly Standings Wrap-up Lint Gate</h1><div class="card"><p><code><?php echo h(REAL_FILE_NAME);?></code></p><p><?php echo h($msg);?></p><?php if($lint!==null):?><pre><?php echo h($lint['output']);?></pre><?php endif;?><form method="post" style="display:inline"><input type="hidden" name="action" value="stage"><button>Stage + Lint Real Installer</button></form> <?php if($ready):?><a href="<?php echo h(REAL_FILE_NAME);?>">Open Real Installer</a><?php endif;?></div></body></html>
